def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def two_sum(nums, target):
    seen = {}  # number -> index
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            i = seen[complement]
            return (i, j)
        seen[num] = j
    return None

def caesar(text, shift):
    result = []
    for char in text:
        if 'A' <= char <= 'Z':
            # Uppercase letter
            new_char = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            result.append(new_char)
        elif 'a' <= char <= 'z':
            # Lowercase letter
            new_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            result.append(new_char)
        else:
            # Non-letter character, keep unchanged
            result.append(char)
    return ''.join(result)

def is_balanced(s):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if bracket_map[char] != top:
                return False

    return len(stack) == 0

def rle_encode(s):
    if not s:
        return ''

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(current_char + str(count))
            current_char = s[i]
            count = 1

    # Don't forget the last run
    result.append(current_char + str(count))

    return ''.join(result)
